// Calibration of the decision rules: run the full pipeline on data where the right answer is known.
//  null    : data generated by a classical rule → quantum should NOT get a green light (false-alarm rate)
//  planted : labels / samples generated by a quantum circuit → measures whether the checker can detect a quantum edge
// Usage: node tests/calibrate.js  (writes tests/calibration.json)
const E = require('../engine.js'); const fs = require('fs');
const out = []; const t0 = Date.now();
const csv = (header, rows) => [header.join(',')].concat(rows.map(r => r.join(','))).join('\n');
const gauss = r => { let u = 0; while (!u) u = r(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * r()); };
function runCls(name, group, text, label) { const t = E.parseCSV(text); const P = E.prepareCls(t, label == null ? t.header.length - 1 : label); const r = E.analyzeCls(P, () => {}); out.push({ task: 'cls', group, name, level: r.verdict.level, best_q: r.quantum.name, q: r.quantum.mean, c: r.models.filter(m => m.kind === 'classical').sort((a, b) => b.mean - a.mean)[0].mean, pQ: r.test.pGreater, pC: r.test.pLess }); console.log(group, name, r.verdict.level, (r.quantum.mean * 100).toFixed(1), ((Date.now() - t0) / 1000).toFixed(0) + 's'); }
function runGen(name, group, text) { const t = E.parseCSV(text); const r = E.analyzeGen(E.prepareGen(t, null), () => {}); out.push({ task: 'gen', group, name, level: r.verdict.level, best_q: r.quantum.name, q: r.quantum.test, c: r.models.filter(m => m.kind === 'classical').sort((a, b) => a.test - b.test)[0].test, pQ: r.test.pGreater, pC: r.test.pLess }); console.log(group, name, r.verdict.level, r.quantum.test.toFixed(3), r.models.map(m => m.test.toFixed(2)).join('/')); }

// ---- classification, null ----
for (const s of [1, 2, 3, 4]) runCls('CDN 合成日誌 seed ' + s, 'null', E.samples.cloudflare(s));
for (const s of [1, 2]) { const r = E.rng(100 + s); const rows = []; for (let i = 0; i < 200; i++) { const x = Array.from({ length: 6 }, () => gauss(r)); const y = x[0] + 0.8 * x[1] - 0.5 * x[2] + 0.5 * gauss(r) > 0 ? 1 : 0; rows.push(x.map(v => v.toFixed(3)).concat([y])); } runCls('線性規則 seed ' + s, 'null', csv(['f1', 'f2', 'f3', 'f4', 'f5', 'f6', 'label'], rows)); }
for (const s of [1, 2]) { const r = E.rng(200 + s); const rows = []; for (let i = 0; i < 200; i++) { const x = Array.from({ length: 6 }, () => gauss(r)); const y = x[0] * x[0] + x[1] * x[1] < 1.4 ? 1 : 0; rows.push(x.map(v => v.toFixed(3)).concat([y])); } runCls('同心圓規則 seed ' + s, 'null', csv(['f1', 'f2', 'f3', 'f4', 'f5', 'f6', 'label'], rows)); }
// ---- classification, planted quantum: label = sign of a function in the ZZ-feature-map kernel space (λ = 0.4) ----
for (const s of [1, 2, 3, 4]) {
  const r = E.rng(300 + s); const N = 200, A = 24; const X = []; for (let i = 0; i < N + A; i++) X.push(Array.from({ length: 6 }, () => gauss(r)));
  const st = X.map(x => E._zzState(x, 0.4)); const alpha = Array.from({ length: A }, () => gauss(r));
  const f = X.slice(0, N).map((_, i) => { let s2 = 0; for (let j = 0; j < A; j++) { const a = st[i], b = st[N + j]; let re = 0, im = 0; for (let k = 0; k < a.re.length; k++) { re += a.re[k] * b.re[k] + a.im[k] * b.im[k]; im += a.re[k] * b.im[k] - a.im[k] * b.re[k]; } s2 += alpha[j] * (re * re + im * im); } return s2; });
  const md = E.stats.median(f); const rows = X.slice(0, N).map((x, i) => x.map(v => v.toFixed(4)).concat([f[i] > md ? 1 : 0]));
  runCls('量子核函數植入標籤 seed ' + s, 'planted', csv(['f1', 'f2', 'f3', 'f4', 'f5', 'f6', 'label'], rows));
}
// ---- generative, null ----
for (const s of [1, 2]) runGen('電商行為 seed ' + s, 'null', E.samples.behavior(s));
for (const s of [1, 2]) { const r = E.rng(400 + s); const rows = []; for (let i = 0; i < 500; i++) { const b = [r() < 0.5]; for (let k = 1; k < 8; k++) b.push(r() < (b[k - 1] ? 0.8 : 0.25)); rows.push(b.map(v => v ? 1 : 0)); } runGen('馬可夫鏈 seed ' + s, 'null', csv(['b1', 'b2', 'b3', 'b4', 'b5', 'b6', 'b7', 'b8'], rows)); }
// ---- generative, planted: samples from a random IQP circuit (exactly the quantum model class) ----
for (const s of [1, 2, 3, 4]) {
  const r = E.rng(500 + s); const nb = 8, N = 256; const th = []; for (let i = 0; i < nb + nb * (nb - 1) / 2; i++) th.push(0.9 * gauss(r));
  const ph = new Float64Array(N); for (let x = 0; x < N; x++) { let p = 0, k = 0; const z = i => ((x >> i) & 1) ? -1 : 1; for (let i = 0; i < nb; i++) p += th[k++] * z(i); for (let i = 0; i < nb; i++) for (let j = i + 1; j < nb; j++) p += th[k++] * z(i) * z(j); ph[x] = p; }
  const re = Float64Array.from(ph, p => Math.cos(p) / 16), im = Float64Array.from(ph, p => Math.sin(p) / 16); E._fwht(re); E._fwht(im);
  const pr = Array.from(re, (v, i) => (v * v + im[i] * im[i]) / 256); const cdf = []; pr.reduce((a, v, i) => (cdf[i] = a + v), 0);
  const rows = []; for (let i = 0; i < 500; i++) { const u = r() * cdf[N - 1]; const x = cdf.findIndex(c => c >= u); rows.push(Array.from({ length: nb }, (_, k) => (x >> k) & 1)); }
  runGen('IQP 線路取樣 seed ' + s, 'planted', csv(['b1', 'b2', 'b3', 'b4', 'b5', 'b6', 'b7', 'b8'], rows));
}
fs.writeFileSync(__dirname + '/calibration.json', JSON.stringify(out, null, 1));
const summ = {}; for (const o of out) { const k = o.task + '/' + o.group; summ[k] = summ[k] || { n: 0, red: 0, yellow: 0, green: 0 }; summ[k].n++; summ[k][o.level]++; }
console.log(JSON.stringify(summ), ((Date.now() - t0) / 1000).toFixed(0) + 's');
